function CookiePolicy(){
  const sections=cookieSections;
  return <div className="kvkk-page cookie-page"><Simple kicker="ÇEREZ POLİTİKASI" title={<>Çerez kullanımı için<br/><em>açık ve anlaşılır bilgilendirme.</em></>} text="EŞLİ TEKNİK web sitesinde çerezlerin ve benzer teknolojilerin hangi amaçlarla kullanılabileceğine ilişkin temel açıklamalar burada yer alır."><section className="legal legal-layout" aria-labelledby="cookie-document-title"><article className="legal-document"><header className="legal-document-head"><span className="section-kicker">ÇEREZLER VE TEKNİK VERİLER</span><h2 id="cookie-document-title">Tercihleriniz için<br/><em>şeffaf bilgilendirme.</em></h2><p>Çerezlerin ne olduğunu, hangi amaçlarla kullanılabileceğini ve tarayıcı ayarlarınız üzerinden tercihlerinizi nasıl yönetebileceğinizi sade bir dille açıklıyoruz.</p></header><div className="legal-sections">{sections.map((section,index)=><section key={section.title}><span>{String(index+1).padStart(2,"0")}</span><div><h3>{section.title}</h3>{section.paragraphs?.map(paragraph=><p key={paragraph}>{paragraph}</p>)}{section.items&&<ul>{section.items.map(item=><li key={item}>{item}</li>)}</ul>}{section.contact&&<div className="legal-contact-strip">{section.contact.map(item=><span key={item}>{item}</span>)}</div>}</div></section>)}</div></article><aside className="legal-aside"><div className="legal-status"><ShieldCheck size={25}/><span><small>ÇEREZ BİLGİLENDİRMESİ</small><strong>Çerez tercihleriyle ilgili<br/>temel bilgiler bu sayfada.</strong></span></div><a className="legal-contact" href={whatsappLink} target="_blank" rel="noreferrer"><MessageCircle size={20}/><span><small> SORUNUZ MU VAR?</small><strong>WhatsApp’tan yazın</strong></span><ArrowRight size={16}/></a><div className="legal-note"><Clock3 size={19}/><p>Çerez ayarlarınızı kullandığınız tarayıcının gizlilik ve site ayarları bölümünden yönetebilirsiniz.</p><a href="/gizlilik-politikasi/">Gizlilik Politikası <ArrowRight size={14}/></a></div></aside></section></Simple></div>
}
export default function ContentPage({path}:{path:string}){const blogPost=blogPosts.find(post=>post.slug===path);if(blogPost)return <BlogArticle post={blogPost}/>;if(path==="/blog"||path==="/blog/"||path==="/bilgi-merkezi"||path==="/bilgi-merkezi/")return <Blog/>;if(pages[path])return <Info d={pages[path]}/>;if(path==="/online-servis-takibi/")return <Tracking/>;if(path==="/tum-markalar/")return <Brands/>;if(path==="/sss/")return <Faq/>;if(path==="/iletisim/")return <Contact/>;if(path==="/hakkimizda/")return <About/>;if(path==="/kvkk/")return <Legal type="KVKK Aydınlatma Metni"/>;if(path==="/gizlilik-politikasi/")return <Privacy/>;if(path==="/cerez-politikasi/")return <CookiePolicy/>;return <Simple kicker="SAYFA BULUNAMADI" title={<>Aradığınız sayfa<br/><em>burada değil.</em></>} text="Ana sayfaya dönerek hizmetleri inceleyebilir veya WhatsApp’tan servis talebi oluşturabilirsiniz."><p className="not-found-link"><a href="/"><ArrowRight size={18}/>Ana sayfaya dönün</a></p></Simple>}
